from pathlib import Path
import json,hashlib,base64,zlib
r=Path('/home/scv/shared/phase497_20261110')
files=json.loads(zlib.decompress(base64.b64decode('')))
manifest={}
for n,t in files.items():
 p=r/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(t,encoding='utf-8');manifest[n]=hashlib.sha256(p.read_bytes()).hexdigest()
 assert manifest[n]==hashlib.sha256(t.encode()).hexdigest()
(r/'POSTPROCESS_CODE_SHA.json').write_text(json.dumps(manifest,indent=2))
print('FINAL_ARCHIVE_ACCEPTED')
